importScripts("https://cdn.jsdelivr.net/pyodide/v0.25.0/full/pyodide.js");

function sendPatch(patch, buffers, msg_id) {
  self.postMessage({
    type: 'patch',
    patch: patch,
    buffers: buffers
  })
}

async function startApplication() {
  console.log("Loading pyodide!");
  self.postMessage({type: 'status', msg: 'Loading pyodide'})
  self.pyodide = await loadPyodide();
  self.pyodide.globals.set("sendPatch", sendPatch);
  console.log("Loaded!");
  await self.pyodide.loadPackage("micropip");
  const env_spec = ['https://tigi-prof-tigi.github.io/tgmaster-afe-python/apps/_vendor/wheels/bokeh-3.4.3-py3-none-any.whl', 'https://tigi-prof-tigi.github.io/tgmaster-afe-python/apps/_vendor/wheels/panel-1.4.5-py3-none-any.whl', 'pyodide-http==0.2.1', 'contextlib', 'html', 'io', 'math', 'pathlib', 'statistics']
  for (const pkg of env_spec) {
    let pkg_name;
    if (pkg.endsWith('.whl')) {
      pkg_name = pkg.split('/').slice(-1)[0].split('-')[0]
    } else {
      pkg_name = pkg
    }
    self.postMessage({type: 'status', msg: `Installing ${pkg_name}`})
    try {
      await self.pyodide.runPythonAsync(`
        import micropip
        await micropip.install('${pkg}');
      `);
    } catch(e) {
      console.log(e)
      self.postMessage({
	type: 'status',
	msg: `Error while installing ${pkg_name}`
      });
    }
  }
  console.log("Packages loaded!");
  self.postMessage({type: 'status', msg: 'Executing code'})
  const code = `
  \nimport asyncio\n\nfrom panel.io.pyodide import init_doc, write_doc\n\ninit_doc()\n\n# === FICHIER GENERE \u2014 ne pas editer (voir exercices.py et app.py) ===\n# -*- coding: utf-8 -*-\n"""Banque d'exercices Python \u2014 Instruments financiers et gestion de portefeuille (B3-AFE n\xb06).\n\nTgMaster University (prononcer "Tiji Master University").\n\nChaque exercice est un dictionnaire :\n  id        : identifiant court unique\n  seance    : numero de seance source (alignement avec les .md et les TPs Excel)\n  titre     : libelle affiche dans le menu deroulant\n  consigne  : enonce en Markdown (donnees + travail demande)\n  starter   : code de depart pre-rempli dans l'editeur (avec les donnees deja saisies)\n  solution  : solution de reference. Le moteur l'execute UNE fois au demarrage pour\n              en deduire les valeurs attendues des variables verifiees. On ne code donc\n              jamais "en dur" un resultat : la verite vient du calcul lui-meme.\n  verifs    : liste de controles. Chaque controle = la variable que l'etudiant doit\n              produire, la tolerance absolue acceptee, et l'unite affichee.\n\nLes donnees numeriques reprennent le contexte BRVM / UEMOA des 4 TPs Excel du cours :\n  TP1 obligation (10 000 FCFA, coupon 6 %, 5 ans, YTM 8 %)\n  TP2 action Gordon-Shapiro + multiples\n  TP3 portefeuille 2 actifs + MEDAF (taux sans risque UEMOA ~4 %)\n  TP4 options (valeur intrinseque, payoff)\n"""\n\nEXERCICES = [\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s02_obligation_coupon_prix",\n        "seance": 2,\n        "titre": "S2 \xb7 Obligation \u2014 coupon et prix",\n        "consigne": """\n### Valorisation d'une obligation du Tr\xe9sor (BRVM / UMOA-Titres)\n\nL'\xc9tat de C\xf4te d'Ivoire \xe9met une obligation **remboursable in fine au pair**.\n\n| Param\xe8tre | Valeur |\n|-----------|--------|\n| Valeur nominale (pair) | 10 000 FCFA |\n| Taux de coupon annuel | 6 % |\n| Maturit\xe9 | 5 ans |\n| Taux de march\xe9 exig\xe9 (YTM) | 8 % |\n\n**Travail demand\xe9 :**\n1. Calculer le **coupon annuel** \u2192 variable \`coupon\`\n2. Calculer le **prix** de l'obligation par actualisation des flux \u2192 variable \`prix\`\n\nRappel : Prix = coupon \xd7 [1 \u2212 (1+r)^(\u2212n)] / r + nominal \xd7 (1+r)^(\u2212n)\n""",\n        "starter": """# Donnees\nnominal = 10000\ntaux_coupon = 0.06\nn = 5\nr = 0.08   # YTM (taux de marche)\n\n# 1) Coupon annuel\ncoupon = ...\n\n# 2) Prix par actualisation des flux\nprix = ...\n\nprint("coupon =", coupon)\nprint("prix   =", round(prix, 2), "FCFA")\n""",\n        "solution": """\nnominal = 10000\ntaux_coupon = 0.06\nn = 5\nr = 0.08\ncoupon = nominal * taux_coupon\nprix = coupon * (1 - (1 + r) ** -n) / r + nominal * (1 + r) ** -n\n""",\n        "verifs": [\n            {"var": "coupon", "tol": 0.5, "unite": "FCFA"},\n            {"var": "prix", "tol": 1.0, "unite": "FCFA"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s03_duration_sensibilite",\n        "seance": 3,\n        "titre": "S3 \xb7 Obligation \u2014 duration de Macaulay et sensibilit\xe9",\n        "consigne": """\n### Duration de Macaulay et risque de taux\n\nOn reprend l'obligation de la s\xe9ance 2 (nominal 10 000 FCFA, coupon 6 %, 5 ans, YTM 8 %).\n\n**Travail demand\xe9 :**\n1. Construire la liste des flux (5 coupons, + le nominal la derni\xe8re ann\xe9e).\n2. Calculer la **duration de Macaulay** \u2192 variable \`duration\`\n   (moyenne des dur\xe9es pond\xe9r\xe9e par la valeur actuelle des flux).\n3. En d\xe9duire la **sensibilit\xe9** (duration modifi\xe9e) \u2192 variable \`sensibilite\`\n\nRappels :\n- Duration = \u03a3 ( t \xd7 VA(flux_t) ) / Prix\n- Sensibilit\xe9 = Duration / (1 + r)\n""",\n        "starter": """nominal = 10000\ncoupon = 600\nn = 5\nr = 0.08\n\n# Flux annee par annee : coupon chaque annee, + nominal la derniere annee\nflux = [coupon] * n\nflux[-1] = flux[-1] + nominal\n\n# Prix (somme des flux actualises)\nprix = sum(f / (1 + r) ** t for t, f in enumerate(flux, start=1))\n\n# 1) Somme des (t x VA du flux)\nsomme_pond = ...\n\n# 2) Duration de Macaulay\nduration = ...\n\n# 3) Sensibilite (duration modifiee)\nsensibilite = ...\n\nprint("prix        =", round(prix, 2))\nprint("duration    =", round(duration, 4), "ans")\nprint("sensibilite =", round(sensibilite, 4))\n""",\n        "solution": """\nnominal = 10000\ncoupon = 600\nn = 5\nr = 0.08\nflux = [coupon] * n\nflux[-1] = flux[-1] + nominal\nprix = sum(f / (1 + r) ** t for t, f in enumerate(flux, start=1))\nsomme_pond = sum(t * f / (1 + r) ** t for t, f in enumerate(flux, start=1))\nduration = somme_pond / prix\nsensibilite = duration / (1 + r)\n""",\n        "verifs": [\n            {"var": "duration", "tol": 0.01, "unite": "ans"},\n            {"var": "sensibilite", "tol": 0.01, "unite": ""},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s05_gordon_shapiro",\n        "seance": 5,\n        "titre": "S5 \xb7 Action \u2014 mod\xe8le de Gordon-Shapiro",\n        "consigne": """\n### \xc9valuation d'une action par le mod\xe8le de Gordon-Shapiro (DDM)\n\nUne soci\xe9t\xe9 cot\xe9e \xe0 la BRVM verse un dividende. On suppose une croissance constante\ndes dividendes \xe0 l'infini.\n\n| Param\xe8tre | Valeur |\n|-----------|--------|\n| Dividende attendu l'an prochain (D\u2081) | 250 FCFA |\n| Taux de croissance des dividendes (g) | 4 % |\n| Taux de rendement exig\xe9 (k) | 11 % |\n\n**Travail demand\xe9 :** calculer le **prix th\xe9orique** de l'action \u2192 variable \`prix\`\n\nRappel : Prix = D\u2081 / (k \u2212 g)\n""",\n        "starter": """D1 = 250\ng = 0.04\nk = 0.11\n\n# Prix par le modele de Gordon-Shapiro\nprix = ...\n\nprint("prix =", round(prix, 2), "FCFA")\n""",\n        "solution": """\nD1 = 250\ng = 0.04\nk = 0.11\nprix = D1 / (k - g)\n""",\n        "verifs": [\n            {"var": "prix", "tol": 1.0, "unite": "FCFA"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s06_multiples_per",\n        "seance": 6,\n        "titre": "S6 \xb7 Action \u2014 \xe9valuation par les multiples (PER)",\n        "consigne": """\n### \xc9valuation par les multiples boursiers\n\nOn \xe9value une action par comparaison sectorielle (m\xe9thode des multiples).\n\n| Param\xe8tre | Valeur |\n|-----------|--------|\n| B\xe9n\xe9fice par action (BPA) | 600 FCFA |\n| PER moyen du secteur (BRVM) | 8 |\n\n**Travail demand\xe9 :**\n1. Calculer le **prix estim\xe9** par les multiples \u2192 variable \`prix\`\n2. Sachant que le cours observ\xe9 est de **4 200 FCFA**, calculer le **PER observ\xe9**\n   de l'action \u2192 variable \`per_observe\`\n\nRappels :\n- Prix = BPA \xd7 PER\n- PER = Cours / BPA\n""",\n        "starter": """bpa = 600\nper_secteur = 8\ncours_observe = 4200\n\n# 1) Prix estime par les multiples\nprix = ...\n\n# 2) PER observe de l'action\nper_observe = ...\n\nprint("prix        =", round(prix, 2), "FCFA")\nprint("PER observe =", round(per_observe, 2))\n""",\n        "solution": """\nbpa = 600\nper_secteur = 8\ncours_observe = 4200\nprix = bpa * per_secteur\nper_observe = cours_observe / bpa\n""",\n        "verifs": [\n            {"var": "prix", "tol": 0.5, "unite": "FCFA"},\n            {"var": "per_observe", "tol": 0.05, "unite": ""},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s07_rentabilite_risque",\n        "seance": 7,\n        "titre": "S7 \xb7 Rentabilit\xe9 et risque d'un actif",\n        "consigne": """\n### Rentabilit\xe9 moyenne et risque d'un actif\n\nOn dispose de la s\xe9rie des rentabilit\xe9s annuelles d'une action sur 5 ans :\n**+8 %, \u22123 %, +12 %, +5 %, \u22122 %**.\n\n**Travail demand\xe9 :**\n1. Calculer la **rentabilit\xe9 moyenne** \u2192 variable \`rendement_moyen\`\n2. Calculer le **risque** mesur\xe9 par l'**\xe9cart-type d'\xe9chantillon** (n\u22121)\n   \u2192 variable \`ecart_type\`\n\nAstuce : le module \`statistics\` est disponible (\`mean\`, \`stdev\`).\n""",\n        "starter": """import statistics\n\nrentabilites = [0.08, -0.03, 0.12, 0.05, -0.02]\n\n# 1) Rentabilite moyenne\nrendement_moyen = ...\n\n# 2) Ecart-type d'echantillon (risque)\necart_type = ...\n\nprint("rendement moyen =", round(rendement_moyen * 100, 2), "%")\nprint("ecart-type      =", round(ecart_type * 100, 2), "%")\n""",\n        "solution": """\nimport statistics\nrentabilites = [0.08, -0.03, 0.12, 0.05, -0.02]\nrendement_moyen = statistics.mean(rentabilites)\necart_type = statistics.stdev(rentabilites)\n""",\n        "verifs": [\n            {"var": "rendement_moyen", "tol": 0.0005, "unite": ""},\n            {"var": "ecart_type", "tol": 0.0005, "unite": ""},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s08_portefeuille_2actifs",\n        "seance": 8,\n        "titre": "S8 \xb7 Portefeuille 2 actifs \u2014 rendement et risque",\n        "consigne": """\n### Rendement et risque d'un portefeuille \xe0 2 actifs (Markowitz)\n\nUn gestionnaire d'Abidjan compose un portefeuille de deux actions A et B.\n\n| Param\xe8tre | Actif A | Actif B |\n|-----------|---------|---------|\n| Poids | 60 % | 40 % |\n| Rendement esp\xe9r\xe9 | 10 % | 6 % |\n| Volatilit\xe9 (\xe9cart-type) | 20 % | 12 % |\n\nCoefficient de **corr\xe9lation** entre A et B : **0,30**.\n\n**Travail demand\xe9 :**\n1. Rendement esp\xe9r\xe9 du portefeuille \u2192 \`rendement_p\`\n2. Risque (\xe9cart-type) du portefeuille \u2192 \`risque_p\`\n\nRappels :\n- E(Rp) = w\u2090\xb7E(R\u2090) + w\u1d66\xb7E(R\u1d66)\n- Var(Rp) = (w\u2090\xb7\u03c3\u2090)\xb2 + (w\u1d66\xb7\u03c3\u1d66)\xb2 + 2\xb7w\u2090\xb7w\u1d66\xb7\u03c3\u2090\xb7\u03c3\u1d66\xb7\u03c1\n- \u03c3p = \u221aVar(Rp)\n""",\n        "starter": """wa, wb = 0.60, 0.40\nEa, Eb = 0.10, 0.06\nsa, sb = 0.20, 0.12\nrho = 0.30\n\n# 1) Rendement espere du portefeuille\nrendement_p = ...\n\n# 2) Variance puis ecart-type du portefeuille\nvar_p = ...\nrisque_p = ...\n\nprint("rendement_p =", round(rendement_p * 100, 2), "%")\nprint("risque_p    =", round(risque_p * 100, 2), "%")\n""",\n        "solution": """\nwa, wb = 0.60, 0.40\nEa, Eb = 0.10, 0.06\nsa, sb = 0.20, 0.12\nrho = 0.30\nrendement_p = wa * Ea + wb * Eb\nvar_p = (wa * sa) ** 2 + (wb * sb) ** 2 + 2 * wa * wb * sa * sb * rho\nrisque_p = var_p ** 0.5\n""",\n        "verifs": [\n            {"var": "rendement_p", "tol": 0.0005, "unite": ""},\n            {"var": "risque_p", "tol": 0.0005, "unite": ""},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s09_medaf_capm",\n        "seance": 9,\n        "titre": "S9 \xb7 MEDAF \u2014 rendement exig\xe9 d'un actif",\n        "consigne": """\n### Rendement exig\xe9 par le MEDAF (CAPM)\n\nSur le march\xe9 r\xe9gional UEMOA :\n\n| Param\xe8tre | Valeur |\n|-----------|--------|\n| Taux sans risque (bon du Tr\xe9sor UEMOA, Rf) | 4 % |\n| B\xeata de l'action (\u03b2) | 1,2 |\n| Rendement esp\xe9r\xe9 du march\xe9 (Rm) | 10 % |\n\n**Travail demand\xe9 :**\n1. Calculer la **prime de risque de march\xe9** \u2192 \`prime_marche\`\n2. Calculer le **rendement exig\xe9** par le MEDAF \u2192 \`rendement_exige\`\n\nRappel : E(Ri) = Rf + \u03b2 \xd7 (Rm \u2212 Rf)\n""",\n        "starter": """rf = 0.04\nbeta = 1.2\nrm = 0.10\n\n# 1) Prime de risque du marche\nprime_marche = ...\n\n# 2) Rendement exige (MEDAF / CAPM)\nrendement_exige = ...\n\nprint("prime marche    =", round(prime_marche * 100, 2), "%")\nprint("rendement exige =", round(rendement_exige * 100, 2), "%")\n""",\n        "solution": """\nrf = 0.04\nbeta = 1.2\nrm = 0.10\nprime_marche = rm - rf\nrendement_exige = rf + beta * (rm - rf)\n""",\n        "verifs": [\n            {"var": "prime_marche", "tol": 0.0005, "unite": ""},\n            {"var": "rendement_exige", "tol": 0.0005, "unite": ""},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "s10_option_call_payoff",\n        "seance": 10,\n        "titre": "S10 \xb7 Option d'achat (call) \u2014 valeur intrins\xe8que et r\xe9sultat",\n        "consigne": """\n### Option d'achat (call) : valeur intrins\xe8que et r\xe9sultat \xe0 l'\xe9ch\xe9ance\n\nUn investisseur ach\xe8te une **option d'achat (call)** sur une action.\n\n| Param\xe8tre | Valeur |\n|-----------|--------|\n| Prix d'exercice (strike, K) | 5 000 FCFA |\n| Cours du sous-jacent \xe0 l'\xe9ch\xe9ance (S_T) | 5 800 FCFA |\n| Prime pay\xe9e \xe0 l'achat | 300 FCFA |\n\n**Travail demand\xe9 :**\n1. Valeur intrins\xe8que du call \xe0 l'\xe9ch\xe9ance \u2192 \`valeur_intrinseque\`\n2. R\xe9sultat net de l'acheteur (payoff \u2212 prime) \u2192 \`resultat_net\`\n\nRappels :\n- Valeur intrins\xe8que (call) = max(S_T \u2212 K, 0)\n- R\xe9sultat net acheteur = valeur intrins\xe8que \u2212 prime\n""",\n        "starter": """K = 5000      # prix d'exercice\nS_T = 5800    # cours a l'echeance\nprime = 300\n\n# 1) Valeur intrinseque du call\nvaleur_intrinseque = ...\n\n# 2) Resultat net de l'acheteur\nresultat_net = ...\n\nprint("valeur intrinseque =", valeur_intrinseque, "FCFA")\nprint("resultat net       =", resultat_net, "FCFA")\n""",\n        "solution": """\nK = 5000\nS_T = 5800\nprime = 300\nvaleur_intrinseque = max(S_T - K, 0)\nresultat_net = valeur_intrinseque - prime\n""",\n        "verifs": [\n            {"var": "valeur_intrinseque", "tol": 0.5, "unite": "FCFA"},\n            {"var": "resultat_net", "tol": 0.5, "unite": "FCFA"},\n        ],\n    },\n\n    # ================================================================== #\n    #  TIER AVANCE \u2014 exercices multi-etapes (fonctions, boucles,         #\n    #  iteration, optimisation, decision). Niveau MBA / \u2605\u2605\u2605.            #\n    # ================================================================== #\n    {\n        "id": "adv_ytm_dichotomie",\n        "seance": 2,\n        "niveau": "avance",\n        "titre": "A1 \xb7 Obligation \u2014 trouver le YTM par dichotomie",\n        "consigne": """\n### Taux actuariel (YTM) d'une obligation par recherche it\xe9rative\n\nUne obligation du Tr\xe9sor UEMOA se **n\xe9gocie sur le march\xe9 \xe0 9 201,46 FCFA**.\nSes caract\xe9ristiques :\n\n| Param\xe8tre | Valeur |\n|-----------|--------|\n| Nominal (rembours\xe9 in fine) | 10 000 FCFA |\n| Coupon annuel | 600 FCFA |\n| Maturit\xe9 | 5 ans |\n\nLe **YTM** (taux actuariel) est le taux \`r\` qui rend la somme des flux actualis\xe9s\n\xe9gale au prix de march\xe9. Il n'existe pas de formule directe : on le **cherche par\ndichotomie** (on resserre un intervalle [bas ; haut] jusqu'\xe0 tomber sur le prix).\n\n**Travail demand\xe9 :**\n1. Compl\xe9ter la fonction \`prix(r)\` qui actualise les flux au taux \`r\`.\n2. Compl\xe9ter la boucle de dichotomie qui ajuste \`bas\`/\`haut\` selon que le prix\n   calcul\xe9 est trop \xe9lev\xe9 ou trop bas.\n3. R\xe9cup\xe9rer le taux trouv\xe9 dans la variable \`ytm\`.\n\nAstuce : le prix d'une obligation **d\xe9cro\xeet** quand le taux monte. Donc si\n\`prix(milieu) > cible\`, le taux est trop bas \u2192 il faut remonter \`bas\`.\n""",\n        "starter": """nominal = 10000\ncoupon = 600\nn = 5\ncible = 9201.46   # prix observe sur le marche\n\nflux = [coupon] * n\nflux[-1] = flux[-1] + nominal\n\ndef prix(r):\n    # Somme des flux actualises au taux r\n    return sum(f / (1 + r) ** t for t, f in enumerate(flux, start=1))\n\n# Dichotomie : on cherche r dans [bas ; haut]\nbas, haut = 0.0001, 0.50\nfor _ in range(100):\n    milieu = (bas + haut) / 2\n    p = prix(milieu)\n    if abs(p - cible) < 0.01:\n        break\n    if p > cible:        # prix trop eleve -> taux trop bas -> remonter 'bas'\n        bas = milieu\n    else:                # prix trop bas  -> taux trop haut -> descendre 'haut'\n        haut = milieu\n\n# Taux actuariel trouve\nytm = ...\n\nprint("YTM =", round(ytm * 100, 3), "%")\nprint("prix au YTM trouve =", round(prix(ytm), 2))\n""",\n        "solution": """\nnominal = 10000\ncoupon = 600\nn = 5\ncible = 9201.46\nflux = [coupon] * n\nflux[-1] = flux[-1] + nominal\n\ndef prix(r):\n    return sum(f / (1 + r) ** t for t, f in enumerate(flux, start=1))\n\nbas, haut = 0.0001, 0.50\nfor _ in range(100):\n    milieu = (bas + haut) / 2\n    p = prix(milieu)\n    if abs(p - cible) < 0.01:\n        break\n    if p > cible:\n        bas = milieu\n    else:\n        haut = milieu\nytm = milieu\n""",\n        "verifs": [\n            {"var": "ytm", "tol": 0.0005, "unite": ""},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "adv_duration_convexite",\n        "seance": 3,\n        "niveau": "avance",\n        "titre": "A2 \xb7 Risque de taux \u2014 estimation duration vs prix r\xe9el",\n        "consigne": """\n### La duration suffit-elle ? Estimation lin\xe9aire contre prix r\xe9el\n\nOn reprend l'obligation (nominal 10 000, coupon 600, 5 ans) au taux de march\xe9\n\`r = 8 %\`. Les taux montent brutalement de **+100 points de base** (passage \xe0 9 %).\n\nLa **sensibilit\xe9** (duration modifi\xe9e) donne une estimation *lin\xe9aire* de la\nvariation de prix. Mais le vrai prix se recalcule avec le nouveau taux. L'\xe9cart\nentre les deux est d\xfb \xe0 la **convexit\xe9**.\n\n**Travail demand\xe9 :**\n1. Calculer \`prix0\`, \`duration\`, puis \`sensibilite\` (= duration / (1+r)).\n2. Estimer le nouveau prix avec la sensibilit\xe9 \u2192 \`prix_estime\`\n   (formule : \`prix0 \xd7 (1 \u2212 sensibilite \xd7 \u0394r)\`).\n3. Recalculer le **vrai** prix au taux de 9 % \u2192 \`prix_reel\`.\n4. En d\xe9duire l'**erreur d'estimation** \`erreur\` = \`prix_reel \u2212 prix_estime\`\n   (elle doit \xeatre positive : la convexit\xe9 joue en faveur du d\xe9tenteur).\n""",\n        "starter": """nominal = 10000\ncoupon = 600\nn = 5\nr = 0.08\ndr = 0.01   # choc de +100 points de base\n\nflux = [coupon] * n\nflux[-1] = flux[-1] + nominal\n\ndef prix(taux):\n    return sum(f / (1 + taux) ** t for t, f in enumerate(flux, start=1))\n\nprix0 = prix(r)\n\n# 1) Duration de Macaulay puis sensibilite\nsomme_pond = sum(t * f / (1 + r) ** t for t, f in enumerate(flux, start=1))\nduration = somme_pond / prix0\nsensibilite = ...\n\n# 2) Estimation lineaire du nouveau prix (via la sensibilite)\nprix_estime = ...\n\n# 3) Vrai prix au taux r + dr\nprix_reel = ...\n\n# 4) Erreur d'estimation (effet de convexite)\nerreur = ...\n\nprint("prix0       =", round(prix0, 2))\nprint("sensibilite =", round(sensibilite, 4))\nprint("prix_estime =", round(prix_estime, 2))\nprint("prix_reel   =", round(prix_reel, 2))\nprint("erreur      =", round(erreur, 2))\n""",\n        "solution": """\nnominal = 10000\ncoupon = 600\nn = 5\nr = 0.08\ndr = 0.01\nflux = [coupon] * n\nflux[-1] = flux[-1] + nominal\n\ndef prix(taux):\n    return sum(f / (1 + taux) ** t for t, f in enumerate(flux, start=1))\n\nprix0 = prix(r)\nsomme_pond = sum(t * f / (1 + r) ** t for t, f in enumerate(flux, start=1))\nduration = somme_pond / prix0\nsensibilite = duration / (1 + r)\nprix_estime = prix0 * (1 - sensibilite * dr)\nprix_reel = prix(r + dr)\nerreur = prix_reel - prix_estime\n""",\n        "verifs": [\n            {"var": "prix_estime", "tol": 1.0, "unite": "FCFA"},\n            {"var": "prix_reel", "tol": 1.0, "unite": "FCFA"},\n            {"var": "erreur", "tol": 0.5, "unite": "FCFA"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "adv_ddm_deux_etages",\n        "seance": 5,\n        "niveau": "avance",\n        "titre": "A3 \xb7 Action \u2014 DDM \xe0 2 \xe9tages (croissance puis perp\xe9tuit\xe9)",\n        "consigne": """\n### Mod\xe8le des dividendes actualis\xe9s \xe0 deux \xe9tages\n\nGordon-Shapiro suppose une croissance constante *\xe0 l'infini* \u2014 irr\xe9aliste pour une\nentreprise en forte expansion. Le **mod\xe8le \xe0 2 \xe9tages** distingue :\n\n- **Phase 1 (forte croissance)** : le dividende cro\xeet de **+12 %/an pendant 4 ans**.\n- **Phase 2 (maturit\xe9)** : ensuite, croissance perp\xe9tuelle de **+4 %/an**.\n\nDonn\xe9es : dernier dividende vers\xe9 \`D0 = 200 FCFA\`, taux de rendement exig\xe9 \`k = 11 %\`.\n\n**Travail demand\xe9 :**\n1. Dans la boucle, calculer chaque dividende \`D1\u2026D4\` et **cumuler sa valeur\n   actuelle** dans \`va_dividendes\`.\n2. Calculer le dividende de l'ann\xe9e 5 (\`D5 = D4 \xd7 1,04\`) puis la **valeur\n   terminale** en fin d'ann\xe9e 4 : \`VT = D5 / (k \u2212 g2)\`.\n3. Actualiser \`VT\` sur 4 ans et l'ajouter \u2192 prix total \`prix\`.\n\nRappel : actualiser un flux de l'ann\xe9e t = flux / (1+k)^t.\n""",\n        "starter": """D0 = 200\ng1 = 0.12   # phase 1 : 4 ans\ng2 = 0.04   # phase 2 : perpetuite\nk = 0.11\nannees_phase1 = 4\n\n# 1) Phase 1 : dividendes annuels et somme de leurs valeurs actuelles\nD = D0\nva_dividendes = 0.0\nfor t in range(1, annees_phase1 + 1):\n    D = D * (1 + g1)          # dividende de l'annee t\n    va_dividendes = va_dividendes + ...   # ajouter sa valeur actuelle\n\n# A ce stade, D vaut D4 (dernier dividende de la phase 1)\nD4 = D\n\n# 2) Valeur terminale en fin d'annee 4\nD5 = ...\nVT = ...\n\n# 3) Prix = VA des dividendes phase 1 + VA de la valeur terminale\nprix = va_dividendes + ...\n\nprint("VA dividendes =", round(va_dividendes, 2))\nprint("valeur term.  =", round(VT, 2))\nprint("prix          =", round(prix, 2), "FCFA")\n""",\n        "solution": """\nD0 = 200\ng1 = 0.12\ng2 = 0.04\nk = 0.11\nannees_phase1 = 4\nD = D0\nva_dividendes = 0.0\nfor t in range(1, annees_phase1 + 1):\n    D = D * (1 + g1)\n    va_dividendes = va_dividendes + D / (1 + k) ** t\nD4 = D\nD5 = D4 * (1 + g2)\nVT = D5 / (k - g2)\nprix = va_dividendes + VT / (1 + k) ** annees_phase1\n""",\n        "verifs": [\n            {"var": "va_dividendes", "tol": 1.0, "unite": "FCFA"},\n            {"var": "VT", "tol": 1.0, "unite": "FCFA"},\n            {"var": "prix", "tol": 1.0, "unite": "FCFA"},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "adv_portefeuille_variance_min",\n        "seance": 8,\n        "niveau": "avance",\n        "titre": "A4 \xb7 Portefeuille \xe0 variance minimale (recherche du poids)",\n        "consigne": """\n### Trouver le portefeuille de variance minimale (2 actifs)\n\nDeux actions A et B :\n\n| Param\xe8tre | Actif A | Actif B |\n|-----------|---------|---------|\n| Volatilit\xe9 (\u03c3) | 20 % | 12 % |\n\nCorr\xe9lation \`\u03c1 = 0,30\`. On cherche le poids \`wa\` (investi en A, le reste en B)\nqui **minimise le risque** du portefeuille.\n\n**Travail demand\xe9 :** balayer tous les poids de 0 \xe0 1 (pas de 0,01), calculer le\nrisque pour chacun, et **m\xe9moriser le poids qui donne le plus petit risque**\n(strat\xe9gie *argmin*).\n\n1. Compl\xe9ter la fonction \`risque(wa)\` (\xe9cart-type du portefeuille).\n2. Compl\xe9ter la boucle qui garde le meilleur poids dans \`w_optimal\` et le risque\n   associ\xe9 dans \`risque_min\`.\n\nRappel : Var = (wa\xb7\u03c3a)\xb2 + (wb\xb7\u03c3b)\xb2 + 2\xb7wa\xb7wb\xb7\u03c3a\xb7\u03c3b\xb7\u03c1 , avec wb = 1 \u2212 wa.\n""",\n        "starter": """sa, sb = 0.20, 0.12\nrho = 0.30\n\ndef risque(wa):\n    wb = 1 - wa\n    var = ...\n    return var ** 0.5\n\n# Balayage argmin : on teste wa = 0.00, 0.01, ..., 1.00\nw_optimal = 0.0\nrisque_min = risque(0.0)\nfor i in range(0, 101):\n    wa = i / 100\n    r = risque(wa)\n    if r < risque_min:\n        risque_min = ...\n        w_optimal = ...\n\nprint("w_optimal  =", round(w_optimal, 2))\nprint("risque_min =", round(risque_min * 100, 2), "%")\n""",\n        "solution": """\nsa, sb = 0.20, 0.12\nrho = 0.30\n\ndef risque(wa):\n    wb = 1 - wa\n    var = (wa * sa) ** 2 + (wb * sb) ** 2 + 2 * wa * wb * sa * sb * rho\n    return var ** 0.5\n\nw_optimal = 0.0\nrisque_min = risque(0.0)\nfor i in range(0, 101):\n    wa = i / 100\n    r = risque(wa)\n    if r < risque_min:\n        risque_min = r\n        w_optimal = wa\n""",\n        "verifs": [\n            {"var": "w_optimal", "tol": 0.011, "unite": ""},\n            {"var": "risque_min", "tol": 0.001, "unite": ""},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "adv_sml_alpha",\n        "seance": 9,\n        "niveau": "avance",\n        "titre": "A5 \xb7 Droite de march\xe9 (SML) \u2014 alpha et d\xe9cision d'achat",\n        "consigne": """\n### S\xe9lection de titres avec la SML et l'alpha de Jensen\n\nMarch\xe9 UEMOA : taux sans risque \`Rf = 4 %\`, rendement esp\xe9r\xe9 du march\xe9 \`Rm = 10 %\`.\n\nUn analyste suit 4 actions de la BRVM, avec pour chacune son b\xeata et le rendement\nqu'il **anticipe** :\n\n| Action | \u03b2 | Rendement anticip\xe9 |\n|--------|------|-------------------|\n| A | 0,8 | 10 % |\n| B | 1,2 | 10 % |\n| C | 1,0 | 11 % |\n| D | 1,5 | 13 % |\n\nLe **rendement exig\xe9** par le MEDAF est \`Rf + \u03b2(Rm \u2212 Rf)\`. L'**alpha** = rendement\nanticip\xe9 \u2212 rendement exig\xe9. Un alpha **positif** = titre **sous-\xe9valu\xe9** (\xe0 acheter).\n\n**Travail demand\xe9 :** parcourir la liste, calculer l'alpha de chaque action, puis :\n1. compter combien sont sous-\xe9valu\xe9es \u2192 \`nb_sous_evaluees\`\n2. retenir le **plus grand alpha** \u2192 \`alpha_max\`\n""",\n        "starter": """rf = 0.04\nrm = 0.10\n\nactions = [\n    {"nom": "A", "beta": 0.8, "anticipe": 0.10},\n    {"nom": "B", "beta": 1.2, "anticipe": 0.10},\n    {"nom": "C", "beta": 1.0, "anticipe": 0.11},\n    {"nom": "D", "beta": 1.5, "anticipe": 0.13},\n]\n\nnb_sous_evaluees = 0\nalpha_max = -1.0   # tres petit pour demarrer le max\n\nfor a in actions:\n    exige = ...                  # MEDAF : Rf + beta*(Rm - Rf)\n    alpha = a["anticipe"] - exige\n    if alpha > 0:\n        nb_sous_evaluees = nb_sous_evaluees + 1\n    if alpha > alpha_max:\n        alpha_max = ...\n\nprint("nb sous-evaluees =", nb_sous_evaluees)\nprint("alpha_max        =", round(alpha_max * 100, 2), "%")\n""",\n        "solution": """\nrf = 0.04\nrm = 0.10\nactions = [\n    {"nom": "A", "beta": 0.8, "anticipe": 0.10},\n    {"nom": "B", "beta": 1.2, "anticipe": 0.10},\n    {"nom": "C", "beta": 1.0, "anticipe": 0.11},\n    {"nom": "D", "beta": 1.5, "anticipe": 0.13},\n]\nnb_sous_evaluees = 0\nalpha_max = -1.0\nfor a in actions:\n    exige = rf + a["beta"] * (rm - rf)\n    alpha = a["anticipe"] - exige\n    if alpha > 0:\n        nb_sous_evaluees = nb_sous_evaluees + 1\n    if alpha > alpha_max:\n        alpha_max = alpha\n""",\n        "verifs": [\n            {"var": "nb_sous_evaluees", "tol": 0.5, "unite": ""},\n            {"var": "alpha_max", "tol": 0.0005, "unite": ""},\n        ],\n    },\n    # ------------------------------------------------------------------ #\n    {\n        "id": "adv_straddle_points_morts",\n        "seance": 10,\n        "niveau": "avance",\n        "titre": "A6 \xb7 Strat\xe9gie d'options (straddle) \u2014 points morts",\n        "consigne": """\n### Straddle : payoff et points morts (break-even)\n\nUn investisseur anticipe une **forte variation** du cours d'une action (sans en\nconna\xeetre le sens). Il monte un **straddle** : achat simultan\xe9 d'un call et d'un put\nde m\xeame strike \`K = 5 000 FCFA\`.\n\n| Option | Prime pay\xe9e |\n|--------|-------------|\n| Call (K = 5 000) | 300 FCFA |\n| Put (K = 5 000) | 250 FCFA |\n\nLe r\xe9sultat net \xe0 l'\xe9ch\xe9ance, pour un cours \`S\`, vaut :\n\`max(S \u2212 K, 0) + max(K \u2212 S, 0) \u2212 (prime_call + prime_put)\`.\n\nLa strat\xe9gie est gagnante **hors** d'un intervalle [point mort bas ; point mort haut].\n\n**Travail demand\xe9 :**\n1. Compl\xe9ter la fonction \`payoff_net(S)\`.\n2. Balayer \`S\` de 4 000 \xe0 6 000 (pas de 1 FCFA) et rep\xe9rer les deux cours o\xf9 le\n   r\xe9sultat **passe par z\xe9ro** : le \`borne_basse\` (avant lequel on gagne par le put)\n   et la \`borne_haute\` (au-del\xe0 duquel on gagne par le call).\n\nAstuce : un changement de signe entre \`payoff_net(S-1)\` et \`payoff_net(S)\` signale\nun point mort.\n""",\n        "starter": """K = 5000\nprime_call = 300\nprime_put = 250\ncout_total = prime_call + prime_put\n\ndef payoff_net(S):\n    call = max(S - K, 0)\n    put = ...\n    return call + put - cout_total\n\nborne_basse = None\nborne_haute = None\nprecedent = payoff_net(4000)\nfor S in range(4001, 6001):\n    courant = payoff_net(S)\n    # changement de signe -> point mort\n    if precedent < 0 <= courant:\n        borne_haute = S        # on repasse positif en montant\n    if precedent >= 0 > courant:\n        borne_basse = S - 1    # dernier S encore gagnant en descendant\n    precedent = courant\n\nprint("cout total  =", cout_total)\nprint("borne_basse =", borne_basse)\nprint("borne_haute =", borne_haute)\n""",\n        "solution": """\nK = 5000\nprime_call = 300\nprime_put = 250\ncout_total = prime_call + prime_put\n\ndef payoff_net(S):\n    call = max(S - K, 0)\n    put = max(K - S, 0)\n    return call + put - cout_total\n\nborne_basse = None\nborne_haute = None\nprecedent = payoff_net(4000)\nfor S in range(4001, 6001):\n    courant = payoff_net(S)\n    if precedent < 0 <= courant:\n        borne_haute = S\n    if precedent >= 0 > courant:\n        borne_basse = S - 1\n    precedent = courant\n""",\n        "verifs": [\n            {"var": "borne_basse", "tol": 1.0, "unite": "FCFA"},\n            {"var": "borne_haute", "tol": 1.0, "unite": "FCFA"},\n        ],\n    },\n]\n\n\ndef exercice_par_id(eid):\n    for ex in EXERCICES:\n        if ex["id"] == eid:\n            return ex\n    return None\n\n\n# === app.py ===\n# -*- coding: utf-8 -*-\n"""App Panel \u2014 Exercices Python interactifs\nInstruments financiers et gestion de portefeuille (B3-AFE n\xb06)\nTgMaster University (prononcer "Tiji Master University").\n\nL'etudiant ecrit son code dans l'editeur, clique "Verifier", et l'app :\n  1. execute le code (sortie texte capturee),\n  2. compare la VALEUR des variables attendues a la solution de reference,\n     avec une tolerance numerique (robuste : pas de comparaison de chaines).\n\nLancement local :\n    pip install panel\n    panel serve app.py --show\n\nDeploiement (voir README.md) :\n    - Hugging Face Spaces (Docker) ou Railway  -> mode serveur\n    - panel convert app.py --to pyodide-worker  -> HTML statique (zero serveur),\n      a embarquer dans Moodle via une iframe.\n"""\nimport io\nimport contextlib\nimport math\nimport pathlib\nimport statistics\n\nimport panel as pn\n\n\n# --- Habillage "Indigo clair" (custom_panel.css place a cote de ce fichier) ---\n# CSS inline (compatible Pyodide, aucune lecture de fichier au runtime)\n_RAW_CSS = [r'''\n/* ===========================================================================\n   custom_panel.css \u2014 Habillage "Indigo clair" pour l'app Panel (app.py)\n   \xc0 placer \xe0 c\xf4t\xe9 de app.py. Charg\xe9 automatiquement par app.py (voir ce fichier).\n   Pour changer de direction visuelle : modifier les 6 variables de :root.\n   =========================================================================== */\n@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600&display=swap');\n\n:root {\n  --accent:        #3b46a0;\n  --accent-strong: #2b3576;\n  --accent-soft:   #eef0fb;\n  --page-bg:       #f1f3f9;\n  --surface:       #ffffff;\n  --surface-2:     #f7f8fc;\n  --border:        #e4e7f0;\n  --border-strong: #d2d7e4;\n  --text:          #1b2030;\n  --text-muted:    #687087;\n  --success:       #1b8a52;\n  --danger:        #c0492f;\n  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;\n  --font-mono: 'JetBrains Mono', ui-monospace, Menlo, Consolas, monospace;\n}\n\nbody, .bk-root {\n  font-family: var(--font-sans) !important;\n  color: var(--text);\n  background: var(--page-bg) !important;\n}\n.bk-root .bk-Column { background: transparent; }\n\n/* S\xe9lecteur d'exercice */\nselect.bk-input, .bk-input {\n  font-family: var(--font-sans) !important;\n  border: 1px solid var(--border-strong) !important;\n  border-radius: 8px !important;\n  color: var(--text) !important;\n  background: var(--surface) !important;\n  font-weight: 600;\n  padding: 9px 12px !important;\n}\nselect.bk-input:focus, .bk-input:focus {\n  outline: none !important;\n  border-color: var(--accent) !important;\n  box-shadow: 0 0 0 3px rgba(59,70,160,0.16) !important;\n}\n.bk-input-group label, label.bk {\n  font-weight: 600 !important;\n  color: var(--text-muted) !important;\n  font-size: 12px !important;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n\n/* Boutons */\n.bk-btn {\n  font-family: var(--font-sans) !important;\n  font-weight: 600 !important;\n  border-radius: 8px !important;\n  padding: 9px 16px !important;\n  border: 1px solid transparent !important;\n  transition: background .15s ease, color .15s ease;\n}\n.bk-btn-primary { background: var(--accent) !important; border-color: var(--accent) !important; color: #fff !important; }\n.bk-btn-primary:hover { background: var(--accent-strong) !important; }\n.bk-btn-default { background: var(--surface) !important; color: var(--text-muted) !important; border-color: var(--border-strong) !important; }\n.bk-btn-default:hover { background: var(--surface-2) !important; color: var(--text) !important; }\n.bk-btn-warning { background: transparent !important; color: var(--accent-strong) !important; border-color: var(--border-strong) !important; }\n.bk-btn-warning:hover { background: var(--accent-soft) !important; }\n.bk-btn-warning.bk-active { background: var(--accent-soft) !important; border-color: var(--accent) !important; }\n\n/* \xc9diteur de code (Ace) */\n.bk-root .ace_editor {\n  border: 1px solid var(--border) !important;\n  border-radius: 12px !important;\n  font-family: var(--font-mono) !important;\n  box-shadow: 0 1px 2px rgba(20,26,50,0.06);\n  overflow: hidden;\n}\n\n/* \xc9nonc\xe9 + feedback (panes Markdown) \u2014 plats, sans carte (les cartes sont g\xe9r\xe9es par .main-panel) */\n.bk-root .markdown { line-height: 1.55; }\n.bk-root .markdown h3 { color: var(--text); font-weight: 800; }\n.bk-root .markdown code {\n  font-family: var(--font-mono) !important;\n  background: var(--accent-soft);\n  color: var(--accent-strong);\n  padding: 1.5px 6px; border-radius: 5px; font-size: 0.86em;\n}\n.bk-root .markdown table {\n  border-collapse: separate; border-spacing: 0;\n  border: 1px solid var(--border); border-radius: 10px; overflow: hidden;\n}\n.bk-root .markdown th {\n  background: var(--surface-2); text-align: left;\n  padding: 9px 13px !important; border-bottom: 1px solid var(--border);\n}\n.bk-root .markdown td {\n  padding: 8px 13px !important; border-bottom: 1px solid var(--border);\n  font-variant-numeric: tabular-nums;\n}\n.bk-root .markdown tr:nth-child(even) td { background: var(--surface-2); }\n\n.bk-root hr { border: none; border-top: 1px solid var(--border); margin: 6px 0; }\n\n/* =========================================================================\n   LAYOUT MAQUETTE \u2014 header + progression / sidebar cartes / panneau + \xe9diteur\n   ========================================================================= */\n\n/* --- En-t\xeate gradient + barre de progression --- */\n.app-header {\n  background: linear-gradient(100deg, var(--accent-strong), var(--accent)) !important;\n  border-radius: 16px !important;\n  padding: 18px 26px !important;\n  box-shadow: 0 8px 24px rgba(20,26,50,.14);\n  align-items: center !important;\n}\n.hdr-sub {\n  color: rgba(255,255,255,.72); font-size: 11.5px; font-weight: 600;\n  letter-spacing: .06em; text-transform: uppercase;\n}\n.hdr-title {\n  color: #fff; font-size: 20px; font-weight: 800; letter-spacing: -.01em; margin-top: 3px;\n}\n.prog-wrap { text-align: right; min-width: 200px; }\n.prog-pill {\n  color: #fff; font-size: 13px; font-weight: 700; margin-bottom: 7px;\n}\n.prog-track {\n  width: 200px; height: 9px; border-radius: 99px;\n  background: rgba(255,255,255,.22); overflow: hidden; margin-left: auto;\n}\n.prog-fill {\n  height: 100%; border-radius: 99px; background: #fff;\n  transition: width .35s ease;\n}\n\n/* --- Sidebar \xab Parcours d'exercices \xbb --- */\n.sidebar {\n  background: var(--surface); border: 1px solid var(--border);\n  border-radius: 16px; padding: 16px 14px !important;\n  box-shadow: 0 1px 2px rgba(20,26,50,.06);\n}\n.sb-title { font-size: 14px; font-weight: 800; color: var(--text); }\n.sb-sub { font-size: 11.5px; color: var(--text-muted); margin-top: 1px; margin-bottom: 6px; }\n.section-head {\n  font-size: 10.5px; font-weight: 700; color: var(--text-muted);\n  letter-spacing: .07em; text-transform: uppercase;\n  margin: 14px 6px 6px;\n}\n\n/* Carte exercice = Row [badge | bouton-label | statut] */\n.exo-card {\n  align-items: center !important;\n  flex-wrap: nowrap !important;\n  overflow: hidden !important;\n  border: 1px solid var(--border) !important;\n  border-radius: 11px !important;\n  margin-bottom: 7px !important;\n  padding: 4px 8px !important;\n  background: var(--surface) !important;\n  transition: border-color .15s ease, background .15s ease, box-shadow .15s ease;\n}\n.exo-card:hover { border-color: var(--border-strong) !important; background: var(--surface-2) !important; }\n.exo-card.actif {\n  border-color: var(--accent) !important;\n  background: var(--accent-soft) !important;\n  box-shadow: 0 0 0 3px rgba(59,70,160,.12) !important;\n}\n/* TOUS les enfants flex doivent pouvoir r\xe9tr\xe9cir sous la largeur de leur contenu */\n.exo-card > * { min-width: 0 !important; }\n/* Badge (gauche) et pastille (droite) : taille fixe, ne r\xe9tr\xe9cissent pas */\n.exo-card > *:first-child { flex: 0 0 auto !important; }\n.exo-card > *:last-child  { flex: 0 0 auto !important; }\n/* Le bouton-label au milieu : prend l'espace restant et r\xe9tr\xe9cit */\n.exo-card > *:nth-child(2) { flex: 1 1 auto !important; min-width: 0 !important; }\n\n.exo-badge-sb {\n  font-family: var(--font-mono) !important; font-size: 11px; font-weight: 700;\n  color: var(--accent-strong); background: var(--accent-soft);\n  border: 1px solid var(--border); border-radius: 7px;\n  padding: 4px 7px; min-width: 34px; text-align: center;\n}\n.exo-card.actif .exo-badge-sb { background: #fff; }\n/* Le bouton-label occupe l'espace, transparent et sans bordure, texte tronqu\xe9 proprement */\n.exo-card .bk-btn, .exo-card .bk-btn-default {\n  background: transparent !important; border: none !important; box-shadow: none !important;\n  text-align: left !important; color: var(--text) !important;\n  font-weight: 600 !important; font-size: 12.5px !important;\n  padding: 6px 4px !important; line-height: 1.35 !important;\n  min-width: 0 !important; width: 100% !important; max-width: 100% !important;\n  display: block !important;\n  white-space: nowrap !important; overflow: hidden !important; text-overflow: ellipsis !important;\n}\n.exo-card .bk-btn:hover { background: transparent !important; color: var(--accent-strong) !important; }\n.exo-stat {\n  flex: 0 0 auto; width: 20px; height: 20px; border-radius: 99px;\n  border: 2px solid var(--border-strong);\n  display: flex; align-items: center; justify-content: center;\n  font-size: 12px; color: transparent;\n}\n.exo-card.ok .exo-stat {\n  border-color: var(--success); background: var(--success); color: #fff;\n}\n\n/* --- Panneau principal --- */\n.main-panel {\n  background: var(--surface); border: 1px solid var(--border);\n  border-radius: 16px; padding: 22px 26px !important;\n  box-shadow: 0 1px 2px rgba(20,26,50,.06);\n}\n.exo-head { align-items: center !important; }\n.exo-badge {\n  font-family: var(--font-mono) !important; font-weight: 800; font-size: 14px;\n  color: #fff; background: var(--accent); border-radius: 9px;\n  padding: 7px 11px; margin-right: 4px;\n}\n.exo-h-title { font-size: 18px; font-weight: 800; color: var(--text); }\n.tag-base, .tag-avance {\n  font-size: 10.5px; font-weight: 700; letter-spacing: .04em; text-transform: uppercase;\n  padding: 4px 9px; border-radius: 99px;\n}\n.tag-base { color: var(--accent-strong); background: var(--accent-soft); }\n.tag-avance { color: #fff; background: linear-gradient(100deg, var(--accent-strong), var(--accent)); }\n\n/* --- Fen\xeatre \xe9diteur style macOS --- */\n.editor-window {\n  border: 1px solid var(--border-strong) !important;\n  border-radius: 12px !important; overflow: hidden;\n  box-shadow: 0 6px 18px rgba(20,26,50,.10);\n  background: #fbfbfd;\n}\n.editor-titlebar {\n  display: flex; align-items: center; gap: 9px;\n  background: var(--surface-2); border-bottom: 1px solid var(--border);\n  padding: 8px 13px;\n}\n.editor-titlebar .dot { width: 12px; height: 12px; border-radius: 99px; display: inline-block; }\n.dot-r { background: #ec6a5e; } .dot-y { background: #f4be4f; } .dot-g { background: #61c554; }\n.editor-titlebar .fname {\n  font-family: var(--font-mono) !important; font-size: 12px; color: var(--text-muted);\n  margin-left: 6px;\n}\n.editor-window .ace_editor { border: none !important; border-radius: 0 !important; box-shadow: none !important; }\n\n/* --- Carte feedback --- */\n.feedback-card {\n  background: var(--surface-2); border: 1px solid var(--border);\n  border-radius: 12px; padding: 6px 18px !important; margin-top: 4px !important;\n}\n\n/* --- Corps deux colonnes responsive --- */\n.body-row { align-items: flex-start !important; flex-wrap: wrap !important; gap: 16px; }\n.body-row > div { min-width: 0 !important; }\n.sidebar { flex: 0 0 280px !important; }\n.main-panel { flex: 1 1 420px !important; min-width: 0 !important; }\n/* Sur \xe9cran \xe9troit : la sidebar passe pleine largeur au-dessus du panneau */\n@media (max-width: 820px) {\n  .sidebar { flex-basis: 100% !important; }\n}\n\n''']\n\npn.extension("codeeditor", sizing_mode="stretch_width", raw_css=_RAW_CSS)\n\n# Palette de la maquette (Indigo clair)\nNAVY = "#2b3576"   # accent indigo (titres, messages neutres)\nRED = "#c0492f"    # erreurs\nGREEN = "#1b8a52"  # succes\n\n# Environnement d'execution autorise : modules surs pour du calcul financier.\nSAFE_MODULES = {"math": math, "statistics": statistics}\n\n\n# --------------------------------------------------------------------------- #\n# Moteur d'execution et de verification\n# --------------------------------------------------------------------------- #\ndef executer_code(code):\n    """Execute \`code\` dans un espace de noms neuf.\n    Retourne (namespace, sortie_texte, erreur_ou_None).\n    Pas de subprocess -> compatible Pyodide (WASM, execution dans le navigateur).\n    """\n    ns = dict(SAFE_MODULES)\n    sortie = io.StringIO()\n    erreur = None\n    try:\n        with contextlib.redirect_stdout(sortie):\n            exec(code, ns)  # noqa: S102 - outil pedagogique, execution voulue\n    except Exception as exc:  # noqa: BLE001\n        erreur = f"{type(exc).__name__} : {exc}"\n    return ns, sortie.getvalue(), erreur\n\n\n# Valeurs de reference : calculees UNE fois depuis la solution de chaque exercice.\ndef _valeurs_attendues(ex):\n    ns, _, err = executer_code(ex["solution"])\n    if err:\n        raise RuntimeError(f"Solution invalide pour {ex['id']} : {err}")\n    return {v["var"]: ns[v["var"]] for v in ex["verifs"]}\n\n\nATTENDU = {ex["id"]: _valeurs_attendues(ex) for ex in EXERCICES}\n\n\ndef verifier(ex, code):\n    """Renvoie (ok_global, markdown_feedback)."""\n    # Garde-fou pedagogique : tant qu'il reste des "..." (placeholders a completer),\n    # on ne lance pas le code -> on evite un TypeError cryptique sur Ellipsis.\n    lignes_a_completer = [i for i, ligne in enumerate(code.splitlines(), start=1)\n                          if "..." in ligne]\n    if lignes_a_completer:\n        nums = ", ".join(str(n) for n in lignes_a_completer)\n        return False, (f"<span style='color:{NAVY}'>\u270f\ufe0f Il reste des \`...\` \xe0 "\n                       f"compl\xe9ter (ligne(s) {nums}). Remplace chaque \`...\` par "\n                       f"ta formule, puis clique de nouveau sur "\n                       f"<b>V\xe9rifier</b>.</span>")\n\n    ns, sortie, erreur = executer_code(code)\n\n    lignes = []\n    if sortie.strip():\n        lignes.append("**Sortie de ton code :**")\n        lignes.append("\`\`\`\\n" + sortie.rstrip() + "\\n\`\`\`")\n\n    if erreur:\n        lignes.append(f"<span style='color:{RED}'>\u274c **Erreur d'ex\xe9cution :** "\n                      f"{erreur}</span>")\n        return False, "\\n\\n".join(lignes)\n\n    attendu = ATTENDU[ex["id"]]\n    tous_ok = True\n    details = []\n    for v in ex["verifs"]:\n        nom = v["var"]\n        unite = (" " + v["unite"]) if v["unite"] else ""\n        if nom not in ns or ns[nom] is Ellipsis:\n            tous_ok = False\n            details.append(f"<span style='color:{RED}'>\u274c \`{nom}\` n'est pas "\n                           f"encore calcul\xe9 (il vaut \`...\`).</span>")\n            continue\n        try:\n            val = float(ns[nom])\n        except (TypeError, ValueError):\n            tous_ok = False\n            details.append(f"<span style='color:{RED}'>\u274c \`{nom}\` doit \xeatre un "\n                           f"nombre.</span>")\n            continue\n        ref = float(attendu[nom])\n        if abs(val - ref) <= v["tol"]:\n            details.append(f"<span style='color:{GREEN}'>\u2705 \`{nom}\` = "\n                           f"{_fmt(val)}{unite}</span>")\n        else:\n            tous_ok = False\n            details.append(f"<span style='color:{RED}'>\u274c \`{nom}\` = {_fmt(val)}"\n                           f"{unite} \u2014 ce n'est pas la valeur attendue.</span>")\n\n    lignes.append("\\n".join(details))\n    if tous_ok:\n        lignes.append(f"<h3 style='color:{GREEN}'>\U0001f389 Exercice r\xe9ussi \u2014 "\n                      f"bravo !</h3>")\n    else:\n        lignes.append(f"<span style='color:{NAVY}'>V\xe9rifie tes formules et "\n                      f"r\xe9essaie.</span>")\n    return tous_ok, "\\n\\n".join(lignes)\n\n\ndef _fmt(x):\n    """Affichage lisible : entier si rond, sinon 4 decimales max."""\n    if abs(x - round(x)) < 1e-9:\n        return f"{int(round(x))}"\n    return f"{x:.4f}".rstrip("0").rstrip(".")\n\n\n# --------------------------------------------------------------------------- #\n# Interface \u2014 maquette : en-tete + progression / sidebar cartes / panneau editeur\n# --------------------------------------------------------------------------- #\nimport html as _html\n\nTOTAL = len(EXERCICES)\nsolved = set()                       # ids des exercices reussis\netat = {"id": EXERCICES[0]["id"]}     # exercice courant\n\n\ndef _split_titre(titre):\n    """'A1 \xb7 Obligation \u2014 trouver le YTM' -> ('A1', 'Obligation \u2014 trouver le YTM').\n    'Exercice 1 \xb7 ...' garde le badge tel quel ; sinon numerote."""\n    if "\xb7" in titre:\n        badge, label = titre.split("\xb7", 1)\n        return badge.strip(), label.strip()\n    return "", titre.strip()\n\n\n# --- Widgets de contenu ----------------------------------------------------- #\nconsigne = pn.pane.Markdown(sizing_mode="stretch_width")\nediteur = pn.widgets.CodeEditor(language="python", theme="tomorrow",\n                                height=360, sizing_mode="stretch_width")\nbouton = pn.widgets.Button(name="\u25b6 V\xe9rifier", button_type="primary", width=150)\nbouton_reset = pn.widgets.Button(name="\u21ba R\xe9initialiser", button_type="default",\n                                 width=150)\nbouton_sol = pn.widgets.Toggle(name="\U0001f441 Voir la solution", button_type="warning",\n                               width=160)\nfeedback = pn.pane.Markdown(sizing_mode="stretch_width")\n\nexo_head = pn.pane.HTML(sizing_mode="stretch_width")\ntitlebar = pn.pane.HTML(sizing_mode="stretch_width")\nprogress = pn.pane.HTML()\n\n\ndef _titlebar_html(eid):\n    n = next((i for i, e in enumerate(EXERCICES, 1) if e["id"] == eid), 1)\n    return ("<div class='editor-titlebar'>"\n            "<span class='dot dot-r'></span><span class='dot dot-y'></span>"\n            "<span class='dot dot-g'></span>"\n            f"<span class='fname'>exercice_{n:02d}.py</span></div>")\n\n\ndef _exo_head_html(ex):\n    badge, label = _split_titre(ex["titre"])\n    avance = ex.get("niveau") == "avance"\n    tag = ("<span class='tag-avance'>Avanc\xe9 \u2605\u2605\u2605</span>" if avance\n           else "<span class='tag-base'>Base \u2605</span>")\n    badge_html = (f"<span class='exo-badge'>{_html.escape(badge)}</span>"\n                  if badge else "")\n    return ("<div class='exo-head' style='display:flex;align-items:center;gap:12px'>"\n            f"{badge_html}"\n            f"<span class='exo-h-title'>{_html.escape(label)}</span>"\n            f"<span style='flex:1 1 auto'></span>{tag}</div>")\n\n\ndef maj_progress():\n    pct = round(100 * len(solved) / TOTAL)\n    progress.object = (\n        "<div class='prog-wrap'>"\n        f"<div class='prog-pill'>{len(solved)} / {TOTAL} r\xe9ussis</div>"\n        f"<div class='prog-track'><div class='prog-fill' style='width:{pct}%'></div></div>"\n        "</div>")\n\n\n# --- Cartes de la sidebar --------------------------------------------------- #\n# Une carte = Row[badge | bouton-label | pastille statut], css togglee a l'execution.\n# Bokeh 3.x rend chaque widget dans son propre shadow root : le CSS global\n# (.exo-card .bk-btn) ne traverse PAS ces frontieres. On injecte donc le style\n# directement dans le shadow root de chaque composant via stylesheets=[...].\ncartes = {}     # eid -> pn.Row\n_boutons_sb = {}\n_stats_sb = {}  # eid -> pn.pane.HTML (pastille statut)\n\n# Pastilles statut : styles INLINE (le selecteur .exo-card.ok .exo-stat ne traverse\n# pas le shadow root du pane HTML \u2014 on change donc directement le contenu du pane).\n_STAT_BASE = ("width:20px;height:20px;border-radius:99px;"\n              "border:2px solid #d2d7e4;display:flex;align-items:center;"\n              "justify-content:center;font-size:12px;color:transparent")\n_STAT_OK = ("width:20px;height:20px;border-radius:99px;"\n            "border:2px solid #1b8a52;background:#1b8a52;color:#fff;"\n            "display:flex;align-items:center;justify-content:center;font-size:12px")\n_STAT_VIDE = f"<div style='{_STAT_BASE}'>\u2713</div>"\n_STAT_PLEIN = f"<div style='{_STAT_OK}'>\u2713</div>"\n\n# Style injecte dans le shadow root de la Row (carte) : fixe les flex des enfants.\nROW_SHEET = """\n:host { align-items: center; }\n.bk-panel-models-markup-HTML { flex: 0 0 auto !important; }\n.bk-panel-models-widgets-Button { flex: 1 1 auto !important; min-width: 0 !important; }\n"""\n\n# Style injecte dans le shadow root du Button-label : transparent, titre sur 2 lignes (lisible).\nBTN_SHEET = """\n:host { width: 100%; min-width: 0; }\n.bk-btn, .bk-btn-default {\n  background: transparent !important; border: none !important; box-shadow: none !important;\n  color: #1b2030 !important; text-align: left !important;\n  font-weight: 600 !important; font-size: 12.5px !important;\n  padding: 6px 4px !important; line-height: 1.3 !important;\n  display: block !important; width: 100% !important; max-width: 100% !important;\n  min-width: 0 !important;\n  white-space: normal !important; overflow-wrap: break-word !important; word-break: normal !important;\n}\n.bk-btn:hover, .bk-btn-default:hover { background: transparent !important; color: #2b3576 !important; }\n"""\n\n\ndef _make_carte(ex):\n    badge, label = _split_titre(ex["titre"])\n    b = pn.widgets.Button(name=label, button_type="default", sizing_mode="stretch_width",\n                          stylesheets=[BTN_SHEET])\n    b.on_click(lambda evt, eid=ex["id"]: select(eid))\n    _boutons_sb[ex["id"]] = b\n    stat = pn.pane.HTML(_STAT_VIDE, width=26)\n    _stats_sb[ex["id"]] = stat\n    badge_pane = pn.pane.HTML(f"<div class='exo-badge-sb'>{_html.escape(badge or '\u2022')}</div>",\n                              width=46)\n    row = pn.Row(badge_pane, b, stat, css_classes=["exo-card"],\n                 stylesheets=[ROW_SHEET], sizing_mode="stretch_width")\n    cartes[ex["id"]] = row\n    return row\n\n\ndef _maj_cartes():\n    for eid, row in cartes.items():\n        cls = ["exo-card"]\n        if eid in solved:\n            cls.append("ok")\n        if eid == etat["id"]:\n            cls.append("actif")\n        row.css_classes = cls\n        _stats_sb[eid].object = _STAT_PLEIN if eid in solved else _STAT_VIDE\n\n\n# --- Selection / verification ---------------------------------------------- #\ndef select(eid):\n    etat["id"] = eid\n    ex = exercice_par_id(eid)\n    exo_head.object = _exo_head_html(ex)\n    consigne.object = ex["consigne"]\n    editeur.value = ex["starter"]\n    titlebar.object = _titlebar_html(eid)\n    feedback.object = ""\n    bouton_sol.value = False\n    _maj_cartes()\n\n\ndef on_verifier(event):\n    eid = etat["id"]\n    ex = exercice_par_id(eid)\n    ok, md = verifier(ex, editeur.value)\n    feedback.object = md\n    if ok and eid not in solved:\n        solved.add(eid)\n        _maj_cartes()\n        maj_progress()\n\n\ndef on_reset(event):\n    ex = exercice_par_id(etat["id"])\n    editeur.value = ex["starter"]\n    feedback.object = ""\n    bouton_sol.value = False\n\n\ndef on_solution(event):\n    ex = exercice_par_id(etat["id"])\n    editeur.value = ex["solution"].strip() if bouton_sol.value else ex["starter"]\n\n\nbouton.on_click(on_verifier)\nbouton_reset.on_click(on_reset)\nbouton_sol.param.watch(on_solution, "value")\n\n\n# --- Assemblage de la sidebar ---------------------------------------------- #\nsidebar_items = [\n    pn.pane.HTML("<div class='sb-title'>Parcours d'exercices</div>"\n                 "<div class='sb-sub'>Instruments financiers &amp; portefeuille</div>"),\n]\n_base = [e for e in EXERCICES if e.get("niveau") != "avance"]\n_avance = [e for e in EXERCICES if e.get("niveau") == "avance"]\nif _base:\n    sidebar_items.append(pn.pane.HTML("<div class='section-head'>Exercices de base \u2605</div>"))\n    sidebar_items += [_make_carte(e) for e in _base]\nif _avance:\n    sidebar_items.append(pn.pane.HTML("<div class='section-head'>Exercices avanc\xe9s \u2605\u2605\u2605</div>"))\n    sidebar_items += [_make_carte(e) for e in _avance]\n\nsidebar = pn.Column(*sidebar_items, css_classes=["sidebar"],\n                    sizing_mode="stretch_width")\n\n# --- En-tete ---------------------------------------------------------------- #\nheader = pn.Row(\n    pn.pane.HTML(\n        "<div class='hdr-sub'>TgMaster University \xb7 B3 \u2014 AFE</div>"\n        "<div class='hdr-title'>Exercices Python \u2014 Instruments financiers &amp; portefeuille</div>"),\n    pn.HSpacer(),\n    progress,\n    css_classes=["app-header"], sizing_mode="stretch_width",\n)\n\n# --- Panneau principal ------------------------------------------------------ #\neditor_win = pn.Column(titlebar, editeur, css_classes=["editor-window"],\n                       sizing_mode="stretch_width")\nmain = pn.Column(\n    exo_head,\n    consigne,\n    editor_win,\n    pn.Row(bouton, bouton_reset, bouton_sol),\n    pn.pane.HTML("<div style='font-weight:700;color:#2b3576;margin-top:4px'>R\xe9sultat</div>"),\n    pn.Column(feedback, css_classes=["feedback-card"], sizing_mode="stretch_width"),\n    css_classes=["main-panel"], sizing_mode="stretch_width",\n)\n\nbody = pn.Row(sidebar, main, css_classes=["body-row"],\n              sizing_mode="stretch_width")\napp = pn.Column(header, body, sizing_mode="stretch_width", max_width=1240)\n\n# Etat initial\nmaj_progress()\nselect(etat["id"])\n\napp.servable(title="Exercices Python \u2014 AFE 6")\n\n\nawait write_doc()
  `

  try {
    const [docs_json, render_items, root_ids] = await self.pyodide.runPythonAsync(code)
    self.postMessage({
      type: 'render',
      docs_json: docs_json,
      render_items: render_items,
      root_ids: root_ids
    })
  } catch(e) {
    const traceback = `${e}`
    const tblines = traceback.split('\n')
    self.postMessage({
      type: 'status',
      msg: tblines[tblines.length-2]
    });
    throw e
  }
}

self.onmessage = async (event) => {
  const msg = event.data
  if (msg.type === 'rendered') {
    self.pyodide.runPythonAsync(`
    from panel.io.state import state
    from panel.io.pyodide import _link_docs_worker

    _link_docs_worker(state.curdoc, sendPatch, setter='js')
    `)
  } else if (msg.type === 'patch') {
    self.pyodide.globals.set('patch', msg.patch)
    self.pyodide.runPythonAsync(`
    from panel.io.pyodide import _convert_json_patch
    state.curdoc.apply_json_patch(_convert_json_patch(patch), setter='js')
    `)
    self.postMessage({type: 'idle'})
  } else if (msg.type === 'location') {
    self.pyodide.globals.set('location', msg.location)
    self.pyodide.runPythonAsync(`
    import json
    from panel.io.state import state
    from panel.util import edit_readonly
    if state.location:
        loc_data = json.loads(location)
        with edit_readonly(state.location):
            state.location.param.update({
                k: v for k, v in loc_data.items() if k in state.location.param
            })
    `)
  }
}

startApplication()